INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(17201, 'Isaiah 34:9', 'Isaiah', 34, 9, '&nbsp;د ادوم سيندونه به په تارکولو بدل شى، خاوره به يې په ګوګړو بدله شى. ټول مُلک به د تارکولو په شان اور اخستے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17202, 'Isaiah 34:10', 'Isaiah', 34, 10, '&nbsp;دا به شپه او ورځ بليږى او د دې نه به تل لوګے خېژى. هغه مُلک به په هره زمانه کښې خوشے پروت وى تر دې چې څوک مسافر به هم تر همېشه پورې په دې کښې سفر نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17203, 'Isaiah 34:11', 'Isaiah', 34, 11, '&nbsp;ګونګيان او ځنګلى ځناور به دا قبضه کړى، هر قِسمه ځنګلى مارغان به په دې کښې پاتې کيږى. مالِک خُدائ به په خيال سره د دې مُلک ناپ تول وکړى، هغه به دا ناپ تول د دې د تباهۍ دپاره وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17204, 'Isaiah 34:12', 'Isaiah', 34, 12, '&nbsp;هلته به د بادشاهۍ هيڅ هم پاتې نۀ وى، او د هغې ټول مشران به ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17205, 'Isaiah 34:13', 'Isaiah', 34, 13, '&nbsp;د ازغو بوټى او تراخۀ بوټى به هر ځائ کښې د پَخو دېوالونو په ښارونو کښې او قلعو کښې خوارۀ شى او ګيدړان او ګونګيان به په دې کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17206, 'Isaiah 34:14', 'Isaiah', 34, 14, '&nbsp;ځنګلى ځناور او ګيدړان به هلته راغونډ شى او د چېلو په شکل پيريان به په کښې يو بل ته آوازونه کوى. د شپې بلا به هلته راځى چې د آرام ځائ پېدا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17207, 'Isaiah 34:15', 'Isaiah', 34, 15, '&nbsp;ګونګيان به هلته جالې جوړوى، هګۍ به اچوى، بچى به ترې نه راوباسى او وزرو لاندې به يې پټوى، او ساتنه به يې کوى. ټپوسان به هلته راغونډيږى او هر يو سره به خپله ماده وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17208, 'Isaiah 34:16', 'Isaiah', 34, 16, '&nbsp;د مالِک خُدائ کِتاب وګورئ او په هغې کښې لټون وکړئ چې څۀ فرمائى. په دې کِتاب کښې د دې ټول مخلوق نومونه موجود وى او يو به هم په کښې بې‌جوړې نۀ وى. مالِک خُدائ حُکم کړے دے چې هم دغه شان دې وشى، د هغۀ روح به يې پخپله په يو ځائ باندې راغونډ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17209, 'Isaiah 34:17', 'Isaiah', 34, 17, '&nbsp;دا به مالِک خُدائ وى چې په دې ځناورو باندې مُلک تقسيم کړى او هر يو له خپله برخه ورکړى. هغوئ به نسل په نسل په هغه مُلک کښې اوسيږى او د تل دپاره به د هغوئ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17210, 'Isaiah 35:1', 'Isaiah', 35, 1, '&nbsp;صحرا او اوچه زمکه به خوشحالى وکړى، او په بيابان کښې به ګلونه غوټۍ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17211, 'Isaiah 35:2', 'Isaiah', 35, 2, '&nbsp;صحرا به سندرې وائى او د خوشحالۍ چغې به وهى، دا صحرا به د لبنان د غرونو په شان شنه وى او د کرمل غر په شان او شوکت والا او د شارون پټو په شان به زرخېزه وى. نو هر يو کس به د مالِک خُدائ شان او شوکت ووينى، او زمونږ د خُدائ پاک لوئى او عظمت به ووينى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17212, 'Isaiah 35:3', 'Isaiah', 35, 3, '&nbsp;کوم لاسونه چې ستړى شوى دى نو هغې له طاقت ورکړه او هغه ګوډو له طاقت ورکړه چې د کمزورۍ په وجه لړزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17213, 'Isaiah 35:4', 'Isaiah', 35, 4, '&nbsp;څوک چې بې‌حوصلې شوى دى نو هغوئ ته ووايه، ”تکړه شئ او مۀ يرېږئ. خُدائ پاک راروان دے چې تاسو بچ کړى، او ستاسو دشمنانو له سزا ورکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17214, 'Isaiah 35:5', 'Isaiah', 35, 5, '&nbsp;نو د ړندو به سترګې وغړيږى، او د کڼو به غوږونه اورېدل شروع کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17215, 'Isaiah 35:6', 'Isaiah', 35, 6, '&nbsp;ګوډ به د هوسۍ په شان ټوپونه وهى، او ګونګيان به د خوشحالۍ سندرې وائى. په صحرا کښې به چشمې راوځى او په بيابان کښې به د اوبو نِهرونه بهيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17216, 'Isaiah 35:7', 'Isaiah', 35, 7, '&nbsp;د بلېدونکې شګې نه به تالاب جوړ شى، او اوچه زمکه به د چينو نه ډکه شى. چرته چې ګيدړان اوسېدل، نو هلته به د نمژنې زمکې واښۀ او لوخې راوټوکيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17217, 'Isaiah 35:8', 'Isaiah', 35, 8, '&nbsp;هلته به يو لوئ سړک وى، چې نوم به يې ”د پاکوالى لار“ وى. ناپاک خلق به په دې باندې سفر نۀ کوى، ځکه چې دا لار صرف هغه خلقو دپاره مخصوص شوې ده کوم چې په نېغه لار ځى، او کم عقل خلق به په دې لار نۀ شى تلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17218, 'Isaiah 35:9', 'Isaiah', 35, 9, '&nbsp;هلته به زمريان نۀ وى، بد ځناور به په هغه لار باندې نۀ تېريږى او نۀ به هلته پاتې کيږى. خو مالِک خُدائ چې څوک بچ کړى وى نو هغوئ به په هغه لار باندې ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17219, 'Isaiah 35:10', 'Isaiah', 35, 10, '&nbsp;هغوئ چې د چا فديه مالِک خُدائ ورکړې ده هغوئ به واپس راشى او سندرې به وائى، څنګه چې يروشلم ته داخل شى نو د هغوئ زړونه به همېشه د خوشحالۍ نه ډک وى، او هغوئ به دومره زيات خوشحاله وى چې غم او پرېشانۍ به ترې وتښتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17220, 'Isaiah 36:1', 'Isaiah', 36, 1, '&nbsp;د حزقياه بادشاه د بادشاهۍ په څوارلسم کال، د اسور بادشاه سينحرب، د يهوداه د پَخو دېوالونو په ښارونو باندې حمله وکړه او قبضه يې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17221, 'Isaiah 36:2', 'Isaiah', 36, 2, '&nbsp;بيا د اسور بادشاه خپل مشر آفسر ته حُکم وکړو چې حزقياه بادشاه ته د يو لوئ لښکر سره د لکيس نه يروشلم ته لاړ شى. نو آفسر په هغه سړک ودرېدو چرته به چې دهوبيانو جامې وينځلې، دا د هغه وَلې سره نزدې وو چې په دې کښې د بره ډنډ نه اوبۀ راتلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17222, 'Isaiah 36:3', 'Isaiah', 36, 3, '&nbsp;نو د يهوداه درې کسان د هغۀ سره مِلاوېدو له راغلل يعنې، د خِلقياه زوئ اِلياقيم، چې هغه د محل مشر وو، شبناه، د دربار منشى، او د آسف زوئ يوآخ، چا چې د هغه زمانې تاريخ ليکلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17223, 'Isaiah 36:4', 'Isaiah', 36, 4, '&nbsp;د اسور آفسر هغوئ ته ووئيل چې، ”حزقياه ته ووايه چې، لوئ بادشاه د اسور بادشاه وائى چې تۀ په څۀ باندې دومره زړَور يې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17224, 'Isaiah 36:5', 'Isaiah', 36, 5, '&nbsp;ستا خيال دا دے څۀ چې تشې خبرې د فوجى طريقه کار او طاقت ځائ نيولے شى؟ د اسوريانو خِلاف په بغاوت کښې به څوک ستا په خيال ستا مدد وکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17225, 'Isaiah 36:6', 'Isaiah', 36, 6, '&nbsp;تۀ د مِصر نه طمع کوې؟ دا به داسې وى لکه چې د لوخې د پاڼې نه امسا جوړه کړې او چې کله په دې باندې زور واچوې نو دا به ستا لاس غوڅ او زخمى کړى. کله چې څوک د مِصر په بادشاه فِرعون بهروسه وکړى نو هغه هم دغه شان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17226, 'Isaiah 36:7', 'Isaiah', 36, 7, '&nbsp;شايد چې تاسو ووايئ، مونږ په مالِک خُدائ په خپل خُدائ پاک باندې بهروسه لرو. خو دا څنګه کېدے شى؟ ولې چې حزقياه خو د مالِک خُدائ علاقائى عبادتخانې او قربان‌ګاه ختمې کړې، کله چې هغۀ د يهوداه او يروشلم خلقو ته ووئيل چې صِرف د يروشلم قربان‌ګاه وړاندې عبادت کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17227, 'Isaiah 36:8', 'Isaiah', 36, 8, '&nbsp;نو اوس راشئ او زمونږ د مالِک د اسور بادشاه سره يوه سودا وکړئ، زۀ به تاسو له دوه زره آسونه درکړم خو کۀ تاسو د دې دپاره دومره سړى پېدا کړل چې په دې باندې سورلى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17228, 'Isaiah 36:9', 'Isaiah', 36, 9, '&nbsp;تۀ زما د مالِک د اسور د بادشاه د يو وړوکى آفسر مقابله هم نۀ شې کولے نو بيا د مِصر په جنګى ګاډۍ او آسونو باندې د سوَرو کسانو فائده څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17229, 'Isaiah 36:10', 'Isaiah', 36, 10, '&nbsp;ستا خيال دا دے څۀ چې ما د مالِک خُدائ د مدد نه بغېر ستا په مُلک حمله کړې ده او ستا مُلک مې تباه کړے دے؟ ما ته مالِک خُدائ په خپله فرمائيلى دى چې په دې باندې حمله وکړه او تباه يې کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17230, 'Isaiah 36:11', 'Isaiah', 36, 11, '&nbsp;نو اِلياقيم، شبناه او يوآخ هغه آفسر ته ووئيل، ”صاحبه، تۀ زمونږ سره په آرامى ژبه کښې خبرې کوه ځکه چې مونږ په دې ښۀ پوهيږو. مونږ سره په عبرانۍ کښې خبرې مۀ کوه، ځکه چې په دېوال باندې ټول خلق دا اورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17231, 'Isaiah 36:12', 'Isaiah', 36, 12, '&nbsp;هغۀ ورته په جواب کښې ووئيل، ”ستاسو خيال دا دے څۀ چې زما بادشاه دا پېغام صرف تاسو او ستاسو بادشاه له رالېږلے دے څۀ؟ نه، زۀ هغه خلقو ته هم وايم کوم چې په دېوال ناست دى. ستاسو په شان به هغوئ هم خپل غُل وخورى او خپلې متيازې به وڅښى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17232, 'Isaiah 36:13', 'Isaiah', 36, 13, '&nbsp;بيا هغه آفسر ودرېدو او په عبرانۍ کښې يې آواز وکړو، ”د اسور بادشاه پېغام په کولاو غوږونو واورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17233, 'Isaiah 36:14', 'Isaiah', 36, 14, '&nbsp;هغه تاسو له خبردارے درکوى چې حزقياه مۀ پرېږدئ چې دوکه درکړى. حزقياه تاسو نۀ شى بچ کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17234, 'Isaiah 36:15', 'Isaiah', 36, 15, '&nbsp;او هغه دې تاسو په دې دوکه نۀ کړى چې په مالِک خُدائ يقين وکړئ. دا خيال مۀ کوئ چې مالِک خُدائ به ضرور تاسو بچ کړى او چې هغه به زمونږ اسورى لښکر ستاسو د ښار قبضه کولو نه ايسار کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17235, 'Isaiah 36:16', 'Isaiah', 36, 16, '&nbsp;حزقياه ته غوږ مۀ نيسئ. د اسور بادشاه تاسو له حُکم درکوى چې ما سره صُلح وکړئ د ښار نه راوځئ او ما له راشئ. نو بيا به په تاسو کښې هر يو کس خپلو د انګورو باغونو نه انګور خورئ او د خپلو اينځرانو د ونو نه به اينځر خورئ او د خپلو کُوهو نه به اوبۀ څښئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17236, 'Isaiah 36:17', 'Isaiah', 36, 17, '&nbsp;بيا به زۀ راشم او تاسو به يو داسې مُلک ته بوځم لکه چې ستاسو د مُلک په شان به وى، هلته به غله، مے، روټۍ او د انګورو باغونه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17237, 'Isaiah 36:18', 'Isaiah', 36, 18, '&nbsp;حزقياه دې درنه کم عقل جوړ نۀ کړى چې دا خيال مو راولى چې مالِک خُدائ به تاسو بچ کړى. د نورو قومونو خُدايانو د هغوئ مُلکونه د اسور بادشاه نه بچ کړى دى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17238, 'Isaiah 36:19', 'Isaiah', 36, 19, '&nbsp;د حمات او ارفاد خُدايان اوس چرته دى؟ د سفروائم خُدايان چرته دى؟ ولې کوم معبود سامريه زما نه بچ کړے شو څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17239, 'Isaiah 36:20', 'Isaiah', 36, 20, '&nbsp;د هر مُلک خُدايانو کله هم خپل مُلک زمونږ د سلطان نه بچ کړے دے څۀ؟ نو بيا تاسو دا سوچ په څۀ باندې کوئ چې مالِک خُدائ به يروشلم زما نه بچ کړى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17240, 'Isaiah 36:21', 'Isaiah', 36, 21, '&nbsp;خو خلق خاموش وُو او يوه خبره يې هم نۀ کوله ځکه چې حزقياه حُکم ورکړے وو چې، ”هغۀ له جواب مۀ ورکوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17241, 'Isaiah 36:22', 'Isaiah', 36, 22, '&nbsp;نو د خِلقياه زوئ اِلياقيم، چې هغه د محل مشر وو، شبناه، د دربار منشى، او د آسف زوئ يوآخ، کوم چې د تاريخ ليکونکو مشر وو د خفګان نه خپلې جامې وشلولې او حزقياه له واپس لاړل. او چې د اسور آفسر هغوئ ته څۀ وئيلى وُو هغه يې ورته ووئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17242, 'Isaiah 37:1', 'Isaiah', 37, 1, '&nbsp;څنګه چې حزقياه بادشاه د هغوئ بيان واورېدو، نو هغۀ د خفګان نه خپلې جامې وشلولې، د ټاټ جامې يې واغوستلې او د مالِک خُدائ کور ته ننوتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17243, 'Isaiah 37:2', 'Isaiah', 37, 2, '&nbsp;هغۀ د محل مشر آفسر اِلياقيم، د دربار منشى شبناه او مشران اِمامان، د آموص زوئ يشعياه پېغمبر له ولېږل. هغوئ هم د ټاټ جامې اغوستې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17244, 'Isaiah 37:3', 'Isaiah', 37, 3, '&nbsp;هغوئ هغۀ ته ووئيل، ”حزقياه بادشاه فرمائى، نن د خفګان، ملامتيا او شرم ورځ ده. مونږ د هغه ښځې په شان يُو چې ماشوم يې پېدا کېدونکے وى، خو د پېدا کېدو زور نۀ لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17245, 'Isaiah 37:4', 'Isaiah', 37, 4, '&nbsp;شايد چې مالِک خُدائ ستاسو خُدائ پاک به هغه د مشر آفسر خبرې اورېدلې وى څوک چې خپل مالِک د اسور بادشاه رالېږلے وو چې د ژوندى خُدائ پاک په حق کښې يې ګستاخى کړې ده. کله چې مالِک خُدائ ستاسو خُدائ پاک اورېدلى دى نو کېدے شى چې هغۀ ته د دې سزا ورکړى څۀ چې هغۀ وئيلى دى. نو د هغوئ دپاره دُعا کوئ کوم خلق چې تر اوسه پورې ژوندى پاتې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17246, 'Isaiah 37:5', 'Isaiah', 37, 5, '&nbsp;کله چې يشعياه ته د حزقياه بادشاه پېغام مِلاو شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17247, 'Isaiah 37:6', 'Isaiah', 37, 6, '&nbsp;نو هغۀ دا جواب ورولېږلو، ”مالِک خُدائ تا ته فرمائى چې کومې خبرې تا اورېدلې دى د هغې په وجه مۀ يرېږه، هغه خبرې چې د اسور بادشاه نوکرانو کړې دى په هغې کښې يې زما، يعنې د مالِک خُدائ ګستاخى کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17248, 'Isaiah 37:7', 'Isaiah', 37, 7, '&nbsp;ګوره، زۀ به د هغۀ ذِهن بدل کړم او چې کله هغه يوه افواه واورى نو هغه به خپل مُلک ته راواپس شى، او هلته به يې په تُوره باندې د وژلو سبب وګرځم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17249, 'Isaiah 37:8', 'Isaiah', 37, 8, '&nbsp;د اسور مشر آفسر خبر شو چې بادشاه د لکيس نه تلے دے او د لِبناه ښار خِلاف جنګ کوى، نو هغه هلته ورَغلو چې مشوره ترې واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17250, 'Isaiah 37:9', 'Isaiah', 37, 9, '&nbsp;بيا اسوريانو بادشاه له دا خبر ورورسېدو چې مِصرے لښکر په هغوئ باندې د حملې کولو دپاره راروان دے چې مشرى يې د ايتهوپيا ترهاقه بادشاه کوى. کله چې هغه د دې نه خبر شو، نو هغۀ د يهوداه بادشاه حزقياه له دا پېغام ولېږلو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17251, 'Isaiah 37:10', 'Isaiah', 37, 10, '&nbsp;چې هغۀ ته داسې ووائى، ”په کوم خُدائ چې تاسو يقين کوئ هغۀ تاسو ته وئيلى دى چې يروشلم به زما په قبضه کښې نۀ راځى، خو چې په هغۀ باندې دوکه نۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17252, 'Isaiah 37:11', 'Isaiah', 37, 11, '&nbsp;ګورئ، تاسو ته پته ده چې د اسور بادشاهانو ټولو مُلکونو سره څۀ کړى دى، هغوئ يې مکمل تباه کړى دى، نو تاسو به څنګه خلاص شئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17253, 'Isaiah 37:12', 'Isaiah', 37, 12, '&nbsp;زما پلار نيکۀ د جوزان، حاران او رصف ښارونه تباه کړل، او د بيت‌عدن خلق يې ووژل چې کوم په تلسار کښې اوسېدل، او يو قوم هم خپلو معبودانو بچ نۀ کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17254, 'Isaiah 37:13', 'Isaiah', 37, 13, '&nbsp;د حمات، ارفاد، سفروائم، هينع او عِواه ښارونو بادشاهان چرته دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17255, 'Isaiah 37:14', 'Isaiah', 37, 14, '&nbsp;حزقياه بادشاه د پېغام وړونکو نه خط واخستلو او وې ولوستلو. بيا هغه د مالِک خُدائ کور ته لاړو او خط يې هلته د مالِک خُدائ په حضور کښې کېښودو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17256, 'Isaiah 37:15', 'Isaiah', 37, 15, '&nbsp;او حزقياه مالِک خُدائ ته دُعا وکړه چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17257, 'Isaiah 37:16', 'Isaiah', 37, 16, '&nbsp;”اے مالِکه خُدايه، ربُ الافواجه، د بنى اِسرائيلو خُدايه پاکه، ستا تخت د وزرو والا مخلوق دپاسه دے، يواځې تۀ هغه خُدائ پاک يې، چې د دُنيا په ټولو بادشاهانو حکومت کوى. تا زمکه او آسمان پېدا کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17258, 'Isaiah 37:17', 'Isaiah', 37, 17, '&nbsp;اوس، مالِکه خُدايه، مونږ ته غوږ ونيسه او چې په مونږ څۀ کيږى هغې ته وګوره. هغه ټولې خبرې واوره چې سينحرب يې ژوندى خُدائ پاک ته د بې‌عزتۍ دپاره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17259, 'Isaiah 37:18', 'Isaiah', 37, 18, '&nbsp;اے مالِکه خُدايه، دا رښتيا دى چې د اسور بادشاهانو ډېر قومونه تباه کړى دى او د هغوئ زمکې يې شاړې کړې دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17260, 'Isaiah 37:19', 'Isaiah', 37, 19, '&nbsp;او د هغوئ معبودان يې سوزولى دى، خو دا رښتينې خُدايان نۀ وُو او تش د لرګى او کاڼى بُتان وُو چې انسانانو جوړ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17261, 'Isaiah 37:20', 'Isaiah', 37, 20, '&nbsp;نو اوس، اے مالِکه خُدايه، زمونږ خُدايه پاکه، مونږ د اسوريانو بادشاه نه بچ کړه، نو داسې د دُنيا ټولو قومونو ته به پته ولګى چې صرف تۀ خُدائ پاک يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17262, 'Isaiah 37:21', 'Isaiah', 37, 21, '&nbsp;بيا د آموص زوئ يشعياه، حزقياه له يو پېغام ولېږلو چې، ”مالِک خُدائ د بنى اِسرائيلو خُدائ پاک فرمائى، په دې وجه چې تاسو ما ته د اسور د بادشاه سينحرب په حقله دُعا کړې ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17263, 'Isaiah 37:22', 'Isaiah', 37, 22, '&nbsp;دا د مالِک خُدائ کلام دے چې د هغۀ خلاف يې ووئيلو، صيون لور تا ته سپک ګورى او درپورې خندا کوى، پېغله صيون لور د خندا نه سر خوځوى چې کله تاسو تښتئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17264, 'Isaiah 37:23', 'Isaiah', 37, 23, '&nbsp;تا چا پورې خندا وکړه او د چا بې‌عزتى دې وکړه؟ تا د چا خلاف آواز اوچت کړو؟ تا چا ته د غرور په نظر وکتل؟ دا د بنى اِسرائيلو مقدس ذات وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17265, 'Isaiah 37:24', 'Isaiah', 37, 24, '&nbsp;د خپلو پېغام وړونکو په ذريعه تا د مالِک خُدائ سپکاوے کړے دے. تا دا لافې وهلې چې ما د بې‌شمېره جنګى ګاډو سره د لبنان د ټولو نه اوچت غرونه فتح کړى دى. ما هلته د دِيار لوړې ونې او د نختر ښې ونې راوغورزولې دى او زۀ د ځنګلو هغه ګڼو برخو ته رسېدلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17266, 'Isaiah 37:25', 'Isaiah', 37, 25, '&nbsp;ما کوهى وکنستل او په پردو مُلکونو کښې مې اوبۀ وڅښلې او زما فوجيانو د پښو سره د نيل درياب اوچ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17267, 'Isaiah 37:26', 'Isaiah', 37, 26, '&nbsp;ولې تا ته پته نۀ وه چې ما د دې هر څۀ منصوبه ډېره د مخکښې نه جوړه کړې وه؟ او اوس مې داسې وکړل او تا له مې دا طاقت درکړو چې د پَخو دېوالونو ښارونه د خاورو په ډېرو بدل کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17268, 'Isaiah 37:27', 'Isaiah', 37, 27, '&nbsp;کوم خلق چې هلته اوسېدل هغوئ بې‌وسه وُو، هغوئ يرېدلى وُو او مازغو يې کار نۀ کولو. هغوئ د واښو په شان کمزورى وُو، د هغه واښو په شان چې په چت باندې په خپله رازرغون شوى وى او چې کله ګرمه هوا وچليږى نو يک دم مړاوى شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17269, 'Isaiah 37:28', 'Isaiah', 37, 28, '&nbsp;خو ما ته ستا د هر څۀ پته ده، چې څۀ کوې او چرته ځې راځې. ما ته پته ده چې تۀ زما خِلاف څومره غضبناک يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17270, 'Isaiah 37:29', 'Isaiah', 37, 29, '&nbsp;ستا د غضب او غرور نه زۀ خبر يم او اوس به زۀ ستا په پوزه کښې پېزوان او ستا په خولۀ کښې قيضه واچوم او چې په کومه لار راغلے يې نو په هغې به دې واپس ولېږم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17271, 'Isaiah 37:30', 'Isaiah', 37, 30, '&nbsp;بيا يشعياه حزقياه بادشاه ته وفرمائيل، ”زۀ چې څۀ وايم هغه رښتيا دى او دا د هغې ثبوت دے. په دې کال او په بل کال به تۀ صِرف هغه غله خورې کومه به چې په خپله شوې وى، خو په درېم کال به تۀ غله کرې او فصلونه به رېبې او د انګورو باغونه به کرې او د هغې انګور به خورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17272, 'Isaiah 37:31', 'Isaiah', 37, 31, '&nbsp;په يهوداه کښې چې کوم کسان ژوندى پاتې دى، نو هغوئ به د هغه بوټو په شان آباد شى چې جرړې يې په زمکه کښې ژورې ځى او مېوه نيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17273, 'Isaiah 37:32', 'Isaiah', 37, 32, '&nbsp;نو ځکه د يروشلم نه به زما باقى ژوندى پاتې خلق راوځى، او د صيون په غرۀ باندې ژوندى پاتې خلق به خوارۀ شى. د مالِک خُدائ ربُ الافواج غېرت به دا هر څۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17274, 'Isaiah 37:33', 'Isaiah', 37, 33, '&nbsp;مالِک خُدائ د اسور بادشاه په حقله داسې فرمائيلى دى، هغه به دې ښار ته نۀ ننوځى او نۀ به د دې خِلاف يو غشے وولى. يو فوجى به هم د ډال سره دې ښار ته نزدې رانۀ شى او د دې ګېرچاپېره محاصرې دپاره به د خاورو ډېرى جوړ نۀ کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17275, 'Isaiah 37:34', 'Isaiah', 37, 34, '&nbsp;هغه چې په کومه لار راغلے وى نو په هغې به واپس لاړ شى او دې ښار ته به نۀ شى ننوتے. مالِک خُدائ داسې فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17276, 'Isaiah 37:35', 'Isaiah', 37, 35, '&nbsp;زۀ به د خپل ځان او خپل خِدمت کوونکى داؤد د خاطره د دې ښار دِفاع او حِفاظت کوم، او دا به بچ کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17277, 'Isaiah 37:36', 'Isaiah', 37, 36, '&nbsp;په هغه شپه د مالِک خُدائ يوه فرښته د اسوريانو خېمو ته ننوتله او يو سل او پينځۀ اتيا زره فوجيان يې ووژل. او چې کله سحر وختى خلق پاڅېدل نو هر طرف ته مړى پراتۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17278, 'Isaiah 37:37', 'Isaiah', 37, 37, '&nbsp;بيا د اسور بادشاه سينحرب خېمې وويستلې او واپس خپل مُلک ته لاړو. هغه نينوه ته ورسېدو او هلته ايسار شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17279, 'Isaiah 37:38', 'Isaiah', 37, 38, '&nbsp;يوه ورځ چې هغۀ د خپل خُدائ نِسروک په عبادتخانه کښې عبادت کولو، نو د هغۀ دوو زامنو ادرمُلِک او شراضر هغه د خپلو تُورو سره ووژلو او هغوئ بيا د اراراط مُلک ته وتښتېدل. د هغۀ يو بل زوئ اسرحدون د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17280, 'Isaiah 38:1', 'Isaiah', 38, 1, '&nbsp;په هغه ورځو کښې حزقياه بادشاه دومره بيمار شو چې مرګى حاله شو. د آموص زوئ يشعياه پېغمبر هغۀ سره مِلاوېدو له ورَغلو او هغۀ ته يې وفرمائيل، ”مالِک خُدائ تا ته فرمائى چې تۀ خپل کارونه سر ته ورسوه ځکه چې تۀ به نۀ ښۀ کېږې. د مرګ تيارے وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17281, 'Isaiah 38:2', 'Isaiah', 38, 2, '&nbsp;د دې اورېدو سره حزقياه مخ دېوال ته واړولو او مالِک خُدائ ته يې سوال وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17282, 'Isaiah 38:3', 'Isaiah', 38, 3, '&nbsp;”مالِکه خُدايه، هغه راياد کړه، چې ما په وفادارۍ سره ستا خِدمت کړے دے او هغه عمل مې کړے دے چې ستا په نظر کښې صحيح وى.“ او هغۀ ډېر په چغو چغو وژړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17283, 'Isaiah 38:4', 'Isaiah', 38, 4, '&nbsp;بيا د مالِک خُدائ کلام په يشعياه نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17284, 'Isaiah 38:5', 'Isaiah', 38, 5, '&nbsp;”حزقياه له واپس لاړ شه او هغۀ ته ووايه، ما يعنې مالِک خُدائ، ستا د پلار نيکۀ داؤد خُدائ پاک ستا دُعا اورېدلې ده او ستا اوښکې مې ليدلى دى. زۀ به تا پينځلس کاله نور ژوندے وساتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17285, 'Isaiah 38:6', 'Isaiah', 38, 6, '&nbsp;او زۀ به تا او د يروشلم دا ښار د اسور بادشاه نه بچ کړم او هم زۀ به د دې ښار حِفاظت کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17286, 'Isaiah 38:7', 'Isaiah', 38, 7, '&nbsp;دا پېغام يې حزقياه ته واورولو او يشعياه ورته دا هم وفرمائيل، ”مالِک خُدائ به درته يوه نښه وښائى چې هغه به خپله وعده پوره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17287, 'Isaiah 38:8', 'Isaiah', 38, 8, '&nbsp;ګوره، زۀ به د احاز د نمر د ګړۍ سورے لس قدمه وروستو بوځم.“ نو هم داسې وشول سورے لس قدمه وروستو لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17288, 'Isaiah 38:9', 'Isaiah', 38, 9, '&nbsp;کله چې حزقياه د بيمارۍ نه روغ شو، نو هغۀ دا حمد‌و‌ثناء وليکل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17289, 'Isaiah 38:10', 'Isaiah', 38, 10, '&nbsp;ما وئيل چې د ژوند په ښۀ دور کښې زۀ د مړو دُنيا ته روان يم، زما د ژوند باقى ټول کالونه زما نه اخستے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17290, 'Isaiah 38:11', 'Isaiah', 38, 11, '&nbsp;ما وئيل چې د ژوندو په دې دُنيا کښې به زۀ بيا هيڅکله مالِک خُدائ ونۀ وينم او نۀ به د دې دُنيا په اوسېدونکو کښې يو سړے ووينم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17291, 'Isaiah 38:12', 'Isaiah', 38, 12, '&nbsp;زما ژوند په ختمېدو وو، د شپانو د هغه خېمې په شان چې راکوزه کړے شوې وى، د هغه قالين په شان چې مکمل کړے شوے وى او د کډۍ نه کټ کړے شوے وى. ما وئيل چې خُدائ پاک زما ژوند ختموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17292, 'Isaiah 38:13', 'Isaiah', 38, 13, '&nbsp;ټوله شپه ما د درد په وجه چغې وهلې، دا داسې وُو لکه چې زمرے زما هډُوکى ماتوى. ما وئيل چې خُدائ پاک زما ژوند ختموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17293, 'Isaiah 38:14', 'Isaiah', 38, 14, '&nbsp;زما آواز نرے او کمزورے شوے وو، د طوطاګرکى او بلبلې په شان مې چينګارے کولو، او د ګوګوشتکې په آواز مې فرياد کولو. آسمان ته په کتلو سره زما سترګې ستړې شوې. اے مالِکه خُدايه، په ما باندې ظلم کيږى. زما مدد وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17294, 'Isaiah 38:15', 'Isaiah', 38, 15, '&nbsp;خو زۀ څۀ وئيلے شم؟ مالِک خُدائ ما سره خبرې کړې دى او هغۀ دا هر څۀ په ما پخپله کړى دى. اوس به زۀ خپل ژوند په عاجزۍ سره تېروم ځکه چې زۀ په دې پرېشانۍ باندې غالب شوے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17295, 'Isaiah 38:16', 'Isaiah', 38, 16, '&nbsp;اے مالِکه خُدايه، ستا تنبيه ښۀ ده، ځکه چې هم دا انسان د صحت او ژوند طرف ته بوځى. تۀ ما روغ کړه او ژوندے مې پرېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17296, 'Isaiah 38:17', 'Isaiah', 38, 17, '&nbsp;يقيناً چې دا سختى زما دپاره ښۀ وه. ځکه چې تا زۀ د مرګ نه بچ کړم او زما ټول ګناهونه دې شاته وغورزول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17297, 'Isaiah 38:18', 'Isaiah', 38, 18, '&nbsp;خو په قبر کښې هيڅ څوک ستا ثناء صِفت نۀ شى کولے، مړى ستا د وفادارۍ طمع نۀ شى لرلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17298, 'Isaiah 38:19', 'Isaiah', 38, 19, '&nbsp;صرف ژوندى ستا ثناء صِفت کولے شى، لکه څنګه چې زۀ نن ستا ثناء صِفت کوم. پلار خپلو بچو ته ستا وفادارى ښائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17299, 'Isaiah 38:20', 'Isaiah', 38, 20, '&nbsp;مالِک خُدائ زما روغولو ته تيار دے. مونږ به رباب غږوو او ستا ثناء صِفت به کوُو، او چې ترڅو پورې مونږ ژوندى يُو نو ستا په کور کښې به ستا ثناء صِفت کوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17300, 'Isaiah 38:21', 'Isaiah', 38, 21, '&nbsp;يشعياه د حزقياه نوکرانو ته فرمائيلى وُو، ”د اينځر نه مرهم جوړ کړئ او په ناسور يعنې دانه يې ورله وتړئ، نو هغه به روغ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');